function createAccount(balance) {
  return {
    deposit: function (amount) {
      balance += amount;
    },
    withdraw: function (amount) {
      if (balance >= amount) {
        balance -= amount;
      }
    },
    getBalance: function () {
      return balance;
    }
  };
}

var account = createAccount(100);
account.deposit(50);
account.withdraw(20);
console.log(account.getBalance());
